const titles={home:"Tổng quan",knowledge:"Kiến thức Hóa học",practice:"Luyện tập",exam:"Kiểm tra",equations:"Công cụ viết phương trình",lab:"Mô phỏng phản ứng",experiments:"Thí nghiệm ảo",reference:"Thư viện tra cứu",progress:"Tiến độ học tập",notebook:"Sổ lỗi sai",settings:"Cài đặt"};
const chapterData=[
{id:"dien-hoa",num:"01",name:"Điện hóa học",short:"Pin điện và điện phân",icon:"⚡",color:"#e8f7fb",desc:"Phản ứng oxi hóa – khử, pin điện hóa, điện phân và định lượng điện phân.",summary:"Điện hóa học nghiên cứu mối liên hệ giữa phản ứng oxi hóa – khử và năng lượng điện. Cần phân biệt pin điện hóa tự phát tạo dòng điện với bình điện phân dùng nguồn điện ngoài để ép phản ứng xảy ra.",concepts:["Trong phản ứng oxi hóa – khử, chất khử nhường electron và bị oxi hóa; chất oxi hóa nhận electron và bị khử.","Ở pin galvanic: anode là nơi oxi hóa (cực âm), cathode là nơi khử (cực dương). Electron đi trong mạch ngoài từ anode sang cathode.","Ở bình điện phân: anode nối cực dương của nguồn điện, cathode nối cực âm; oxi hóa vẫn xảy ra ở anode và khử vẫn xảy ra ở cathode.","Điện phân nóng chảy chỉ có ion của chất điện li nóng chảy; điện phân dung dịch còn cạnh tranh với sự phóng điện của nước và các ion khác.","Điện lượng Q = I.t; số mol electron n(e) = Q/F, với F xấp xỉ 96 500 C mol⁻¹."],equations:["Zn → Zn²⁺ + 2e⁻ (oxi hóa tại anode của pin Zn–Cu)","Cu²⁺ + 2e⁻ → Cu (khử tại cathode)","2H₂O + 2e⁻ → H₂ + 2OH⁻ (một bán phản ứng có thể xảy ra ở cathode trong dung dịch)","m = (M.I.t)/(n.F) (khi xác định được bán phản ứng tạo chất có n electron)"],uses:["Pin và ắc quy chuyển hóa năng lượng hóa học thành điện năng.","Điện phân được dùng để mạ điện, tinh luyện kim loại và điều chế một số chất."],mistakes:["Đồng nhất anode với cực dương trong mọi hệ. Hãy nhớ anode luôn là nơi oxi hóa; dấu điện cực phụ thuộc loại thiết bị.","Quên xét môi trường dung dịch khi dự đoán sản phẩm điện phân.","Đổi phút sang giây sai khi dùng Q = I.t."]},
{id:"kim-loai",num:"02",name:"Đại cương về kim loại",short:"Tính chất và điều chế kim loại",icon:"⬡",color:"#edf4ff",desc:"Liên kết kim loại, dãy điện hóa, ăn mòn và các phương pháp điều chế.",summary:"Kim loại có xu hướng nhường electron hóa trị, tạo ion dương. Tính chất vật lí đặc trưng gắn với liên kết kim loại; tính chất hóa học phổ biến là tính khử.",concepts:["Liên kết kim loại hình thành do lực hút tĩnh điện giữa ion dương kim loại và electron hóa trị chuyển động tương đối tự do.","Kim loại thường có tính dẫn điện, dẫn nhiệt, ánh kim và tính dẻo.","Mức độ phản ứng của kim loại phụ thuộc bản chất kim loại và điều kiện phản ứng; dãy điện hóa hỗ trợ dự đoán phản ứng thế.","Ăn mòn kim loại là sự phá hủy kim loại hoặc hợp kim do tác dụng của môi trường, có thể là ăn mòn hóa học hoặc điện hóa.","Điều chế kim loại thường dựa trên khử ion kim loại thành nguyên tử: nhiệt luyện, thủy luyện hoặc điện phân."],equations:["Fe + CuSO₄ → FeSO₄ + Cu (phản ứng thế)","Zn + 2HCl → ZnCl₂ + H₂↑","4Fe + 3O₂ → 2Fe₂O₃ (mô hình phản ứng oxi hóa tổng quát)"],uses:["Mạ kim loại, sơn phủ, dùng hợp kim phù hợp môi trường để hạn chế ăn mòn.","Lựa chọn phương pháp điều chế dựa vào độ hoạt động hóa học và tính chất hợp chất."],mistakes:["Cho rằng mọi kim loại đều phản ứng với nước ở điều kiện thường.","Kết luận phản ứng thế chỉ từ việc một kim loại có vẻ hoạt động mạnh hơn mà không xét điều kiện và môi trường.","Nhầm ăn mòn hóa học với ăn mòn điện hóa."]},
{id:"kim-loai-ia",num:"03",name:"Kim loại nhóm IA",short:"Kim loại kiềm",icon:"◉",color:"#fff5e9",desc:"Đặc điểm kim loại kiềm và các hợp chất quan trọng của sodium, potassium.",summary:"Kim loại kiềm có cấu hình electron lớp ngoài cùng ns¹, dễ nhường một electron tạo ion M⁺. Chúng có tính khử mạnh và phản ứng mạnh với nước.",concepts:["Các nguyên tố nhóm IA (kim loại kiềm, trừ hydrogen) có một electron hóa trị ở phân lớp s.","Trong nhóm, bán kính nguyên tử nhìn chung tăng và năng lượng ion hóa thứ nhất giảm từ trên xuống; tính khử thường tăng.","Kim loại kiềm phản ứng với nước tạo hydroxide tương ứng và giải phóng hydrogen.","NaOH là base mạnh; Na₂CO₃ và NaHCO₃ có các phản ứng đặc trưng với acid."],equations:["2Na + 2H₂O → 2NaOH + H₂↑","Na₂CO₃ + 2HCl → 2NaCl + CO₂↑ + H₂O","NaHCO₃ + HCl → NaCl + CO₂↑ + H₂O","2NaHCO₃ → Na₂CO₃ + CO₂↑ + H₂O (đun nóng)"],uses:["NaCl là nguyên liệu quan trọng trong công nghiệp hóa chất.","NaOH dùng trong sản xuất xà phòng, giấy và xử lí một số quy trình công nghiệp.","NaHCO₃ được dùng trong thực phẩm và một số ứng dụng gia dụng phù hợp."],mistakes:["Viết sản phẩm phản ứng Na với nước thành Na₂O.","Quên hệ số khi cân bằng phản ứng carbonate hoặc hydrogen carbonate với acid.","Nhầm độ tan và tính base của các muối carbonate."]},
{id:"kim-loai-iia",num:"04",name:"Kim loại nhóm IIA",short:"Kim loại kiềm thổ",icon:"◌",color:"#eef9f2",desc:"Magnesium, calcium, hợp chất của calcium và độ cứng của nước.",summary:"Kim loại kiềm thổ có hai electron hóa trị ns², thường tạo ion M²⁺. Calcium và hợp chất của calcium liên quan trực tiếp đến đá vôi, vữa, xi măng và xử lí nước.",concepts:["Kim loại nhóm IIA có cấu hình lớp ngoài cùng ns² và số oxi hóa phổ biến +2 trong hợp chất.","CaCO₃ bị nhiệt phân tạo CaO và CO₂; CaO tác dụng với nước tạo Ca(OH)₂.","Nước cứng chứa đáng kể Ca²⁺ và/hoặc Mg²⁺; độ cứng tạm thời thường liên quan đến hydrogencarbonate.","Có thể làm mềm nước bằng kết tủa ion Ca²⁺/Mg²⁺ hoặc các phương pháp trao đổi ion phù hợp."],equations:["CaCO₃ → CaO + CO₂↑ (nhiệt phân)","CaO + H₂O → Ca(OH)₂","Ca(OH)₂ + CO₂ → CaCO₃↓ + H₂O (khi CO₂ vừa đủ)","Ca(HCO₃)₂ → CaCO₃↓ + CO₂↑ + H₂O (đun nóng)"],uses:["Đá vôi là nguyên liệu sản xuất vôi và xi măng.","Ca(OH)₂ được dùng trong xử lí nước và một số quy trình xây dựng.","Nhận biết nước cứng giúp lựa chọn phương pháp xử lí phù hợp."],mistakes:["Không xét lượng CO₂ khi cho CO₂ tác dụng với nước vôi trong; CO₂ dư có thể làm tan kết tủa.","Gọi mọi loại nước cứng là nước cứng tạm thời.","Nhầm CaO với Ca(OH)₂."]},
{id:"phuc-chat",num:"05",name:"Kim loại chuyển tiếp và phức chất",short:"Phức chất và ion phức",icon:"◇",color:"#f1efff",desc:"Tính chất kim loại chuyển tiếp, ion trung tâm, phối tử và số phối trí.",summary:"Phức chất gồm nguyên tử hoặc ion trung tâm liên kết với các phối tử thông qua liên kết cho – nhận. Cấu trúc phối trí giúp giải thích màu sắc và một số tính chất của phức.",concepts:["Kim loại chuyển tiếp dãy thứ nhất thường có phân lớp 3d chưa bão hòa ở nguyên tử hoặc ion thông dụng.","Ion trung tâm thường là ion kim loại; phối tử là tiểu phân có cặp electron tự do có thể cho vào orbital thích hợp của ion trung tâm.","Số phối trí là số nguyên tử cho liên kết trực tiếp với ion trung tâm trong một phức chất.","Một số ion phức có màu đặc trưng; màu quan sát phụ thuộc ion trung tâm, phối tử, hình học và môi trường."],equations:["Cu²⁺ + 4NH₃ ⇌ [Cu(NH₃)₄]²⁺ (phức xanh đậm)","Ag⁺ + 2NH₃ ⇌ [Ag(NH₃)₂]⁺ (phức diammin bạc(I))"],uses:["Phức chất có vai trò trong phân tích hóa học, sinh học, xúc tác và công nghệ vật liệu.","Sự tạo phức có thể dùng để nhận biết ion hoặc thay đổi độ tan của một chất."],mistakes:["Nhầm số phối trí với số oxi hóa của ion trung tâm.","Xác định NH₃ là ion âm; NH₃ là phối tử phân tử trung hòa.","Coi màu của mọi phức đồng(II) là giống nhau bất kể phối tử."]},
{id:"ester-lipid",num:"06",name:"Ester và lipid",short:"Ester, chất béo và xà phòng",icon:"◒",color:"#fff2ec",desc:"Cấu tạo ester, phản ứng thủy phân, chất béo và xà phòng hóa.",summary:"Ester thường chứa nhóm chức –COO–. Chất béo là triester của glycerol với các acid béo; phản ứng thủy phân trong môi trường kiềm tạo glycerol và muối của acid béo.",concepts:["Ester đơn chức, mạch hở thường có dạng RCOOR′; danh pháp thường dựa trên gốc alkyl và gốc carboxylate.","Ester có thể tham gia phản ứng thủy phân trong môi trường acid hoặc base.","Chất béo là triester của glycerol với các acid béo; có thể chứa gốc no hoặc không no.","Xà phòng là muối sodium hoặc potassium của acid béo; đầu ion tương tác với nước, đuôi hydrocarbon tương tác với dầu mỡ."],equations:["RCOOR′ + H₂O ⇌ RCOOH + R′OH (thủy phân acid, điều kiện thích hợp)","RCOOR′ + NaOH → RCOONa + R′OH (xà phòng hóa ester đơn chức)","(RCOO)₃C₃H₅ + 3NaOH → 3RCOONa + C₃H₅(OH)₃"],uses:["Ester được dùng làm dung môi, hương liệu và nguyên liệu tổng hợp.","Xà phòng và chất giặt rửa giúp phân tán dầu mỡ vào nước."],mistakes:["Nhầm thủy phân acid là phản ứng một chiều; phản ứng có cân bằng.","Quên hệ số 3 khi xà phòng hóa triester của glycerol.","Cho rằng xà phòng hoạt động tốt như nhau trong nước mềm và nước cứng."]},
{id:"carbohydrate",num:"07",name:"Carbohydrate",short:"Glucose đến polysaccharide",icon:"⌬",color:"#fff8e8",desc:"Glucose, fructose, sucrose, maltose, tinh bột và cellulose.",summary:"Carbohydrate bao gồm monosaccharide, disaccharide và polysaccharide. Cấu trúc phân tử quyết định khả năng thủy phân và phản ứng nhận biết.",concepts:["Glucose và fructose là monosaccharide có cùng công thức phân tử C₆H₁₂O₆ nhưng cấu tạo khác nhau.","Sucrose gồm gốc glucose và fructose; maltose gồm hai gốc glucose; cả hai là disaccharide.","Tinh bột và cellulose là polysaccharide của các đơn vị glucose nhưng khác kiểu liên kết glycoside và cấu trúc không gian.","Glucose có tính khử; có thể tham gia phản ứng tráng bạc trong điều kiện thích hợp.","Tinh bột tạo màu xanh tím với iodine; đây là phản ứng nhận biết thường dùng."],equations:["C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O (hô hấp/oxi hóa hoàn toàn)","C₁₂H₂₂O₁₁ + H₂O → C₆H₁₂O₆ + C₆H₁₂O₆ (thủy phân sucrose)","(C₆H₁₀O₅)ₙ + nH₂O → nC₆H₁₂O₆ (mô hình thủy phân polysaccharide)"],uses:["Glucose là nguồn năng lượng quan trọng trong sinh học.","Tinh bột là nguồn dự trữ carbohydrate ở thực vật; cellulose góp phần tạo cấu trúc thành tế bào."],mistakes:["Cho rằng mọi disaccharide đều có tính khử giống nhau.","Nhầm phản ứng màu iodine của tinh bột với phản ứng tráng bạc của glucose.","Coi glucose và fructose có cấu tạo giống nhau chỉ vì cùng công thức phân tử."]},
{id:"hop-chat-nito",num:"08",name:"Hợp chất hữu cơ chứa nitrogen",short:"Amine, amino acid và protein",icon:"N",color:"#f1f0ff",desc:"Amine, amino acid, peptide và protein; tính base và liên kết peptide.",summary:"Hợp chất hữu cơ chứa nitrogen có cấu trúc đa dạng. Amine thể hiện tính base; amino acid có cả nhóm amino và carboxyl nên có tính lưỡng tính; peptide hình thành qua liên kết peptide.",concepts:["Amine có thể xem là dẫn xuất của ammonia khi một hay nhiều nguyên tử hydrogen được thay bằng gốc hydrocarbon.","Amine có cặp electron tự do trên nitrogen nên có khả năng nhận proton; độ base phụ thuộc cấu trúc và môi trường.","Amino acid chứa đồng thời nhóm –NH₂ và –COOH; trong dung dịch có thể tồn tại dạng ion lưỡng cực.","Liên kết peptide có dạng –CO–NH–, hình thành giữa nhóm carboxyl của amino acid này và nhóm amino của amino acid khác.","Protein là đại phân tử sinh học gồm các chuỗi polypeptide với cấu trúc không gian đặc thù."],equations:["RNH₂ + H₂O ⇌ RNH₃⁺ + OH⁻ (mô tả tính base của amine)","H₂N–CHR–COOH ⇌ ⁺H₃N–CHR–COO⁻ (dạng ion lưỡng cực)","H₂N–CHR–COOH + H₂N–CHR′–COOH → H₂N–CHR–CO–NH–CHR′–COOH + H₂O"],uses:["Amino acid và protein giữ vai trò cấu trúc, xúc tác và điều hòa trong cơ thể sống.","Amine là nguyên liệu trong sản xuất dược phẩm, phẩm nhuộm và vật liệu."],mistakes:["Nhầm amine với amide; amide có nhóm –CONH–.","Cho rằng amino acid chỉ có tính acid hoặc chỉ có tính base.","Quên nước được tách ra khi hình thành liên kết peptide theo mô hình ngưng tụ."]},
{id:"polymer",num:"09",name:"Polymer và vật liệu polymer",short:"Polymer hóa, polycondensation và vật liệu",icon:"⌘",color:"#eef8fa",desc:"Monomer, mắt xích, trùng hợp, trùng ngưng, nhựa, tơ và cao su.",summary:"Polymer là hợp chất có phân tử khối rất lớn gồm nhiều đơn vị cấu trúc lặp lại. Cần phân biệt monomer, mắt xích và cơ chế hình thành polymer.",concepts:["Polymer gồm nhiều mắt xích liên kết với nhau; monomer là phân tử nhỏ có thể tham gia tạo polymer.","Phản ứng trùng hợp thường kết hợp các monomer không giải phóng phân tử nhỏ; trùng ngưng tạo polymer đồng thời giải phóng phân tử nhỏ như H₂O hoặc HCl tùy hệ.","Polymer có nguồn gốc thiên nhiên, bán tổng hợp hoặc tổng hợp.","Tính chất vật liệu polymer phụ thuộc cấu trúc mạch, khối lượng phân tử, mức độ liên kết ngang và phụ gia."],equations:["nCH₂=CH₂ → (–CH₂–CH₂–)ₙ (polyethylene, trùng hợp cộng)","nCH₂=CHCl → (–CH₂–CHCl–)ₙ (poly(vinyl chloride))","Trùng ngưng: các monomer có ít nhất hai nhóm chức liên kết, đồng thời tách phân tử nhỏ như H₂O; phải viết phương trình cụ thể theo monomer và mắt xích."],uses:["Polymer được dùng sản xuất bao bì, sợi, cao su, thiết bị y tế và vật liệu kỹ thuật.","Giảm rác thải nhựa cần kết hợp thiết kế vật liệu, tái sử dụng, phân loại và công nghệ tái chế phù hợp."],mistakes:["Nhầm monomer với mắt xích polymer.","Gọi mọi phản ứng tạo polymer là trùng hợp.","Coi mọi loại nhựa đều có thể tái chế theo cùng một quy trình."]}
];
const qBank=[
{id:"Q001",chapter:"dien-hoa",type:"mcq",level:1,prompt:"Trong pin điện hóa Zn–Cu đang hoạt động, quá trình oxi hóa xảy ra ở điện cực nào?",options:["Cathode","Anode","Cả hai điện cực","Cầu muối"],answer:"Anode",why:"Anode luôn là nơi xảy ra oxi hóa. Với pin Zn–Cu, Zn nhường electron: Zn → Zn²⁺ + 2e⁻.",optionWhy:{"Cathode":"Cathode là nơi xảy ra quá trình khử.","Cả hai điện cực":"Trong mô tả một pin đang phát điện, mỗi điện cực đảm nhiệm một bán phản ứng: oxi hóa ở anode, khử ở cathode.","Cầu muối":"Cầu muối giúp duy trì trung hòa điện, không phải điện cực diễn ra bán phản ứng."}},
{id:"Q002",chapter:"dien-hoa",type:"mcq",level:2,prompt:"Điện phân NaCl nóng chảy với điện cực trơ, sản phẩm ở cathode là chất nào?",options:["Na","Cl₂","NaOH","H₂"],answer:"Na",why:"Trong NaCl nóng chảy chỉ có Na⁺ và Cl⁻. Tại cathode: Na⁺ + e⁻ → Na.",optionWhy:{"Cl₂":"Chloride bị oxi hóa ở anode, không phải cathode.","NaOH":"Không có nước trong hệ nóng chảy để tạo hydroxide.","H₂":"Không có nước hoặc nguồn hydrogen trong chất điện li nóng chảy."}},
{id:"Q003",chapter:"dien-hoa",type:"short",level:2,prompt:"Một dòng điện không đổi 2,0 A chạy qua bình điện phân trong 965 s. Tính điện lượng Q (đơn vị C).",answer:1930,tol:1,unit:"C",why:"Q = I.t = 2,0 × 965 = 1930 C. Cần đổi thời gian về giây trước khi áp dụng công thức.",common:"Dùng 965 thay vì 965 s hoặc không thống nhất đơn vị thời gian."},
{id:"Q004",chapter:"dien-hoa",type:"tf",level:2,prompt:"Xét các phát biểu về pin điện hóa và bình điện phân.",context:"So sánh hai hệ: pin galvanic tự phát và bình điện phân được nối với nguồn điện một chiều.",statements:[{text:"Ở cả hai hệ, anode đều là nơi xảy ra quá trình oxi hóa.",answer:true,why:"Định nghĩa anode dựa trên quá trình oxi hóa, không dựa trên dấu điện cực."},{text:"Trong pin galvanic, anode là cực dương.",answer:false,why:"Trong pin galvanic, anode là cực âm vì phát electron ra mạch ngoài."},{text:"Trong bình điện phân, cathode nối với cực âm của nguồn điện.",answer:true,why:"Nguồn điện cung cấp electron cho cathode để xảy ra quá trình khử."},{text:"Electron chuyển qua dung dịch điện li từ anode đến cathode.",answer:false,why:"Electron đi trong dây dẫn ngoài; dòng điện trong dung dịch được tải bởi sự chuyển động của ion."}]},
{id:"Q005",chapter:"kim-loai",type:"mcq",level:1,prompt:"Tính chất hóa học đặc trưng phổ biến của kim loại là gì?",options:["Tính oxi hóa","Tính khử","Tính acid","Tính base"],answer:"Tính khử",why:"Kim loại thường nhường electron tạo cation, do đó thể hiện tính khử trong nhiều phản ứng.",optionWhy:{"Tính oxi hóa":"Kim loại có thể nhận electron trong một số trường hợp đặc biệt, nhưng tính chất đặc trưng phổ biến là nhường electron.","Tính acid":"Không phải tính chất hóa học đặc trưng chung của kim loại.","Tính base":"Một số oxide/hydroxide kim loại có tính base, nhưng đó không phải tính chất chung của đơn chất kim loại."}},
{id:"Q006",chapter:"kim-loai",type:"tf",level:3,prompt:"Cho thanh sắt sạch vào dung dịch CuSO₄. Đánh giá các phát biểu.",context:"Phản ứng xảy ra ở điều kiện thường: Fe + CuSO₄ → FeSO₄ + Cu.",statements:[{text:"Sắt bị oxi hóa thành Fe²⁺.",answer:true,why:"Fe nhường 2 electron: Fe → Fe²⁺ + 2e⁻."},{text:"Ion Cu²⁺ nhận electron và bị khử.",answer:true,why:"Cu²⁺ + 2e⁻ → Cu."},{text:"Khối lượng thanh kim loại chắc chắn giảm.",answer:false,why:"Theo phương trình, mỗi mol Fe tan thì một mol Cu bám. Vì M(Cu) lớn hơn M(Fe), khối lượng thanh tăng nếu phản ứng diễn ra theo tỉ lệ này."},{text:"Dung dịch sau phản ứng có thể có màu lục nhạt do ion Fe²⁺.",answer:true,why:"Dung dịch muối Fe²⁺ thường có màu lục nhạt; màu thực tế phụ thuộc nồng độ và điều kiện."}]},
{id:"Q007",chapter:"kim-loai",type:"short",level:2,prompt:"Cho 0,10 mol Fe phản ứng hoàn toàn với CuSO₄ dư theo phương trình Fe + CuSO₄ → FeSO₄ + Cu. Số mol Cu thu được là bao nhiêu?",answer:0.1,tol:0.0001,unit:"mol",why:"Tỉ lệ mol Fe : Cu = 1 : 1. Vì CuSO₄ dư và Fe phản ứng hết nên n(Cu) = 0,10 mol.",common:"Đọc sai hệ số tỉ lượng hoặc dùng số mol của chất dư."},
{id:"Q008",chapter:"kim-loai-ia",type:"mcq",level:2,prompt:"Sản phẩm khí khi sodium phản ứng với nước ở điều kiện thường là gì?",options:["O₂","Cl₂","H₂","CO₂"],answer:"H₂",why:"Phương trình: 2Na + 2H₂O → 2NaOH + H₂↑.",optionWhy:{"O₂":"Oxygen không phải sản phẩm của phản ứng sodium với nước.","Cl₂":"Không có nguồn chlorine trong hệ.","CO₂":"Không có nguồn carbon trong các chất phản ứng."}},
{id:"Q009",chapter:"kim-loai-ia",type:"tf",level:2,prompt:"Đánh giá các phát biểu về sodium hydrogencarbonate (NaHCO₃).",statements:[{text:"NaHCO₃ phản ứng với acid mạnh giải phóng CO₂.",answer:true,why:"HCO₃⁻ nhận proton tạo H₂CO₃, sau đó phân hủy thành CO₂ và H₂O."},{text:"NaHCO₃ là hydroxide kim loại kiềm.",answer:false,why:"NaHCO₃ là muối hydrogencarbonate, không phải hydroxide."},{text:"Khi đun nóng, NaHCO₃ có thể phân hủy tạo Na₂CO₃, CO₂ và H₂O.",answer:true,why:"2NaHCO₃ → Na₂CO₃ + CO₂ + H₂O."},{text:"Trong 1 mol NaHCO₃ có 1 mol nguyên tử sodium.",answer:true,why:"Mỗi công thức NaHCO₃ chứa đúng một nguyên tử Na."}]},
{id:"Q010",chapter:"kim-loai-ia",type:"short",level:1,prompt:"Cần bao nhiêu mol Na để tạo 0,25 mol H₂ khi Na phản ứng hoàn toàn với nước?",answer:0.5,tol:0.001,unit:"mol Na",why:"Từ 2Na + 2H₂O → 2NaOH + H₂, tỉ lệ n(Na):n(H₂) = 2:1. Vậy n(Na) = 2 × 0,25 = 0,50 mol.",common:"Đảo ngược tỉ lệ hệ số trong phương trình."},
{id:"Q011",chapter:"kim-loai-iia",type:"mcq",level:2,prompt:"Khi nung calcium carbonate ở nhiệt độ thích hợp, chất rắn thu được là gì?",options:["Ca(OH)₂","CaO","CaCl₂","CaSO₄"],answer:"CaO",why:"CaCO₃ → CaO + CO₂ khi nung. Đây là phản ứng nhiệt phân.",optionWhy:{"Ca(OH)₂":"Calcium hydroxide tạo ra khi CaO tác dụng với nước.","CaCl₂":"Muốn tạo CaCl₂ cần nguồn chlorine hoặc acid thích hợp.","CaSO₄":"Không có nguồn sulfate trong chất ban đầu."}},
{id:"Q012",chapter:"kim-loai-iia",type:"tf",level:3,prompt:"Xét phản ứng giữa CO₂ và nước vôi trong Ca(OH)₂.",context:"Dung dịch Ca(OH)₂ ban đầu trong, được sục CO₂ từ từ rồi tiếp tục sục CO₂ dư.",statements:[{text:"Khi CO₂ vừa đủ, có thể xuất hiện kết tủa CaCO₃.",answer:true,why:"Ca(OH)₂ + CO₂ → CaCO₃↓ + H₂O."},{text:"Nếu tiếp tục sục CO₂ dư, kết tủa có thể tan dần.",answer:true,why:"CaCO₃ + CO₂ + H₂O → Ca(HCO₃)₂ tan."},{text:"Kết tủa tạo thành là CaSO₄.",answer:false,why:"Sản phẩm kết tủa là calcium carbonate, không có ion sulfate trong hệ."},{text:"Không cần xét lượng CO₂ vì hiện tượng luôn giống nhau.",answer:false,why:"Lượng CO₂ quyết định kết tủa hình thành hay chuyển thành hydrogencarbonate tan."}]},
{id:"Q013",chapter:"kim-loai-iia",type:"short",level:2,prompt:"Nung hoàn toàn 0,20 mol CaCO₃. Số mol CO₂ tối đa thu được là bao nhiêu?",answer:0.2,tol:0.001,unit:"mol",why:"CaCO₃ → CaO + CO₂ có tỉ lệ 1:1. Do đó n(CO₂) = 0,20 mol.",common:"Quên hệ số 1:1 hoặc tự thêm hệ số không có trong phương trình."},
{id:"Q014",chapter:"phuc-chat",type:"mcq",level:2,prompt:"Trong ion phức [Cu(NH₃)₄]²⁺, phối tử là chất nào?",options:["Cu²⁺","NH₃","[Cu(NH₃)₄]²⁺","Electron"],answer:"NH₃",why:"NH₃ có cặp electron tự do trên N và đóng vai trò phối tử cho cặp electron liên kết với ion trung tâm Cu²⁺.",optionWhy:{"Cu²⁺":"Cu²⁺ là ion trung tâm.","[Cu(NH₃)₄]²⁺":"Đây là toàn bộ ion phức, không phải một phối tử đơn lẻ.","Electron":"Electron tham gia liên kết nhưng không phải phối tử trong cách gọi này."}},
{id:"Q015",chapter:"phuc-chat",type:"tf",level:3,prompt:"Đánh giá các nhận định về phức chất [Cu(NH₃)₄]²⁺.",statements:[{text:"Ion trung tâm là Cu²⁺.",answer:true,why:"Cu²⁺ nằm ở trung tâm của cầu phối trí."},{text:"NH₃ là phối tử trung hòa.",answer:true,why:"NH₃ không mang điện tích tổng thể và cho cặp electron tự do."},{text:"Số phối trí của Cu²⁺ trong phức này là 2.",answer:false,why:"Có bốn phân tử NH₃ liên kết với ion trung tâm, nên số phối trí trong mô hình này là 4."},{text:"Điện tích ion phức bằng +2.",answer:true,why:"NH₃ trung hòa, do đó điện tích toàn ion phức bằng điện tích Cu²⁺."}]},
{id:"Q016",chapter:"ester-lipid",type:"mcq",level:2,prompt:"Thủy phân ester đơn chức RCOOR′ trong môi trường kiềm NaOH thường thu được gì?",options:["Acid carboxylic và aldehyde","Muối carboxylate và alcohol","Ketone và nước","Muối carbonate và alcohol"],answer:"Muối carboxylate và alcohol",why:"RCOOR′ + NaOH → RCOONa + R′OH. Đây là phản ứng xà phòng hóa ester đơn chức.",optionWhy:{"Acid carboxylic và aldehyde":"Đó không phải sản phẩm tổng quát của thủy phân kiềm ester.","Ketone và nước":"Không phù hợp với sự cắt liên kết ester trong môi trường kiềm.","Muối carbonate và alcohol":"Không có nhóm carbonate trong ester carboxylic thông thường."}},
{id:"Q017",chapter:"ester-lipid",type:"short",level:2,prompt:"Xà phòng hóa hoàn toàn 0,10 mol triester của glycerol cần bao nhiêu mol NaOH?",answer:0.3,tol:0.001,unit:"mol NaOH",why:"Một phân tử triester có ba liên kết ester. Theo phương trình tổng quát, 1 mol triester cần 3 mol NaOH; vậy cần 0,30 mol.",common:"Dùng tỉ lệ 1:1 như ester đơn chức thay vì xét ba nhóm ester."},
{id:"Q018",chapter:"ester-lipid",type:"tf",level:2,prompt:"Đánh giá các phát biểu về chất béo và xà phòng.",statements:[{text:"Chất béo là triester của glycerol với các acid béo.",answer:true,why:"Đây là định nghĩa cấu tạo cơ bản của chất béo."},{text:"Xà phòng thường là muối sodium hoặc potassium của acid béo.",answer:true,why:"Đầu ion carboxylate ưa nước, đuôi hydrocarbon kị nước."},{text:"Ion Ca²⁺ trong nước cứng có thể tạo muối ít tan với anion của xà phòng.",answer:true,why:"Điều này làm giảm hiệu quả tạo bọt và giặt rửa của xà phòng."},{text:"Xà phòng hóa chất béo chỉ cần một mol NaOH cho mỗi mol chất béo.",answer:false,why:"Triester có ba nhóm ester nên cần ba mol NaOH theo tỉ lệ tổng quát."}]},
{id:"Q019",chapter:"carbohydrate",type:"mcq",level:1,prompt:"Thuốc thử nào thường dùng để nhận biết tinh bột thông qua hiện tượng đổi màu?",options:["Dung dịch iodine","Nước bromine","Dung dịch NaCl","Quỳ tím"],answer:"Dung dịch iodine",why:"Tinh bột tạo phức màu xanh tím với iodine trong điều kiện thử nghiệm thông thường.",optionWhy:{"Nước bromine":"Không phải thuốc thử nhận biết tinh bột đặc trưng trong chương trình phổ thông.","Dung dịch NaCl":"Không tạo hiện tượng màu đặc trưng với tinh bột.","Quỳ tím":"Chỉ thị acid–base, không nhận biết tinh bột."}},
{id:"Q020",chapter:"carbohydrate",type:"tf",level:2,prompt:"Đánh giá các phát biểu về một số carbohydrate.",statements:[{text:"Glucose và fructose có cùng công thức phân tử C₆H₁₂O₆.",answer:true,why:"Chúng là các đồng phân cấu tạo."},{text:"Sucrose được cấu tạo từ glucose và fructose.",answer:true,why:"Liên kết glycoside nối hai đơn vị monosaccharide này."},{text:"Tinh bột cho màu xanh tím với iodine.",answer:true,why:"Đây là phản ứng nhận biết tinh bột thường dùng."},{text:"Cellulose tan tốt trong nước lạnh.",answer:false,why:"Cellulose không tan trong nước lạnh do cấu trúc polymer và mạng liên kết giữa các mạch."}]},
{id:"Q021",chapter:"carbohydrate",type:"short",level:2,prompt:"Thủy phân hoàn toàn 1 mol sucrose tạo ra tổng cộng bao nhiêu mol monosaccharide?",answer:2,tol:0.001,unit:"mol",why:"1 mol sucrose + 1 mol H₂O tạo 1 mol glucose và 1 mol fructose, tổng cộng 2 mol monosaccharide.",common:"Đếm số phân tử sản phẩm mà không phân biệt tổng số mol."},
{id:"Q022",chapter:"hop-chat-nito",type:"mcq",level:2,prompt:"Tính base của amine chủ yếu liên quan đến yếu tố cấu trúc nào?",options:["Cặp electron tự do trên nitrogen","Liên kết đôi C=C","Nhóm carbonyl C=O","Nguyên tử oxygen trong nước"],answer:"Cặp electron tự do trên nitrogen",why:"Nguyên tử nitrogen trong amine có cặp electron tự do có thể nhận proton, thể hiện tính base.",optionWhy:{"Liên kết đôi C=C":"Liên kết này không phải trung tâm nhận proton đặc trưng của amine.","Nhóm carbonyl C=O":"Nhóm carbonyl không phải nguyên nhân cấu trúc chung tạo tính base của amine.","Nguyên tử oxygen trong nước":"Nước là môi trường phản ứng, không phải yếu tố cấu trúc của amine."}},
{id:"Q023",chapter:"hop-chat-nito",type:"tf",level:3,prompt:"Đánh giá các nhận định về amino acid và peptide.",statements:[{text:"Amino acid thông thường chứa nhóm amino và nhóm carboxyl.",answer:true,why:"Hai nhóm chức này tạo nên tính lưỡng tính của amino acid."},{text:"Dạng ion lưỡng cực có thể có nhóm –NH₃⁺ và –COO⁻.",answer:true,why:"Đây là dạng tồn tại quan trọng trong nhiều điều kiện dung dịch."},{text:"Liên kết peptide có dạng –CO–NH–.",answer:true,why:"Liên kết này hình thành giữa nhóm carboxyl và nhóm amino."},{text:"Hình thành liên kết peptide theo mô hình ngưng tụ không giải phóng phân tử nhỏ.",answer:false,why:"Mô hình tạo liên kết peptide từ hai amino acid giải phóng H₂O."}]},
{id:"Q024",chapter:"polymer",type:"mcq",level:2,prompt:"Monomer nào tham gia phản ứng trùng hợp tạo polyethylene (PE)?",options:["CH₂=CH₂","CH₂=CHCl","CH₂=CH–CH₃","H₂N–(CH₂)₆–NH₂"],answer:"CH₂=CH₂",why:"Ethylene có liên kết đôi C=C mở ra để tạo mạch –CH₂–CH₂– lặp lại.",optionWhy:{"CH₂=CHCl":"Monomer này tạo poly(vinyl chloride) (PVC).","CH₂=CH–CH₃":"Propylene tạo polypropylene (PP).","H₂N–(CH₂)₆–NH₂":"Đây là diamine có thể tham gia phản ứng trùng ngưng với hợp chất hai chức thích hợp."}},
{id:"Q025",chapter:"polymer",type:"tf",level:3,prompt:"Đánh giá các nhận định về polymer.",statements:[{text:"Monomer là phân tử nhỏ có thể tham gia tạo polymer.",answer:true,why:"Monomer là nguyên liệu cấu tạo nên polymer."},{text:"Polyethylene được tạo thành từ ethylene qua phản ứng trùng hợp cộng.",answer:true,why:"Liên kết đôi của ethylene mở ra và tạo mạch polymer."},{text:"Mọi polymer đều có thể nóng chảy và tái chế bằng cùng một cách.",answer:false,why:"Polymer nhiệt dẻo, nhiệt rắn và elastomer có hành vi khác nhau; loại vật liệu và phụ gia quyết định quy trình."},{text:"Mắt xích polymer luôn chính là phân tử monomer chưa biến đổi.",answer:false,why:"Mắt xích là đơn vị cấu trúc lặp lại trong mạch polymer, có thể khác cách biểu diễn monomer sau khi liên kết hình thành."}]},
{id:"Q026",chapter:"polymer",type:"short",level:2,prompt:"Một mẫu polyethylene có khối lượng 28 000 g/mol. Lấy khối lượng mol mắt xích –CH₂–CH₂– là 28 g/mol. Bậc polymer hóa trung bình n bằng bao nhiêu?",answer:1000,tol:1,unit:"",why:"n ≈ M_polymer/M_mắt xích = 28 000/28 = 1000.",common:"Dùng khối lượng mol nguyên tử thay vì khối lượng mol của toàn bộ mắt xích."}
];
